export const DICTS: Record<string, Dict> = {
  en, es, fr, pt, ar, sw, hi, id, tl, ur, fa, de, ja, zh, bn,
};

export const LANG_CODES = LANGS.map((l) => l.code);

export function langMeta(code: string): LangMeta {
  return LANGS.find((l) => l.code === code) ?? LANGS[0];
}

export function isRtl(code: string): boolean {
  return langMeta(code).dir === "rtl";
}

/** Translate with graceful fallback: lang → English → the key itself. */
export function translator(code: string): (key: string) => string {
  const dict = DICTS[code] ?? en;
  return (key: string) => dict[key] ?? en[key] ?? key;
}

/** Fill `{name}` placeholders in a translated string.
 *
 *  Word order differs between languages ("Question 2 of 5" is "第2問／全5問" in
 *  Japanese), so a count is never assembled by concatenating translated
 *  fragments in JSX. An unknown placeholder is left literal rather than
 *  rendering "undefined". */
export function fill(s: string, vars: Record<string, string | number>): string {
  return s.replace(/\{(\w+)\}/g, (whole, k: string) =>
    Object.prototype.hasOwnProperty.call(vars, k) ? String(vars[k]) : whole,
  );
}

/** A short date in the reader's own language — the ONE format a deadline (or a
 *  recorded answer's day) is shown in, so two surfaces cannot disagree about
 *  what day the same work is due. Never throws on an unknown locale. */
export function dueLabel(lang: string | undefined, at: number): string {
  try {
    return new Date(at).toLocaleDateString(lang ?? "en", { day: "numeric", month: "short" });
  } catch {
    return new Date(at).toLocaleDateString();
  }
}

